#include "graph_color_bridge.h"
#include "constraint_graph.h"
#include <stddef.h>
uint32_t spGraphTouchingFlag(void){return b2_simTouchingFlag;}
uint32_t spGraphColorCount(void){return B2_GRAPH_COLOR_COUNT;}
bool spExportGraphColor(const void*p,SpGraphColorView*out,uint32_t cs,uint32_t js){if(!p||!out)return false;const b2GraphColor*n=p;if(n->contactSims.count<0||n->jointSims.count<0||n->contactSims.capacity<n->contactSims.count||n->jointSims.capacity<n->jointSims.count||(!n->contactSims.data&&n->contactSims.count)||(!n->jointSims.data&&n->jointSims.count)||(uint32_t)n->contactSims.count>cs||(uint32_t)n->jointSims.count>js||(!out->contacts&&n->contactSims.count)||(!out->joints&&n->jointSims.count))return false;for(int i=0;i<n->contactSims.count;++i)if(!spExportContactSim(n->contactSims.data+i,out->contacts+i))return false;for(int i=0;i<n->jointSims.count;++i)if(!spExportJointSim(n->jointSims.data+i,out->joints+i))return false;out->body_set=n->bodySet;out->contact_count=n->contactSims.count;out->contact_capacity=n->contactSims.capacity;out->joint_count=n->jointSims.count;out->joint_capacity=n->jointSims.capacity;return true;}
bool spImportGraphColorCandidate(const SpGraphColorView*s,void*p){if(!s||!p||s->contact_count>s->contact_capacity||s->joint_count>s->joint_capacity||(!s->contacts&&s->contact_count)||(!s->joints&&s->joint_count))return false;b2GraphColor*n=p;if(n->contactSims.capacity<0||n->jointSims.capacity<0||(uint32_t)n->contactSims.capacity!=s->contact_capacity||(uint32_t)n->jointSims.capacity!=s->joint_capacity||(!n->contactSims.data&&s->contact_capacity)||(!n->jointSims.data&&s->joint_capacity))return false;for(uint32_t i=0;i<s->contact_count;++i)if(!spImportContactSim(s->contacts+i,n->contactSims.data+i))return false;for(uint32_t i=0;i<s->joint_count;++i)if(!spImportJointSim(s->joints+i,n->jointSims.data+i))return false;n->bodySet=s->body_set;n->contactSims.count=s->contact_count;n->jointSims.count=s->joint_count;n->wideConstraints=NULL;n->wideConstraintCount=0;return true;}
bool spGraphColorFixtureRoundTrip(const SpGraphColorView*s,SpGraphColorView*out,uint32_t cs,uint32_t js){if(!s||s->contact_capacity>8||s->joint_capacity>8)return false;b2ContactSim contacts[8];b2JointSim joints[8];b2GraphColor native={0};native.contactSims.data=contacts;native.contactSims.capacity=s->contact_capacity;native.jointSims.data=joints;native.jointSims.capacity=s->joint_capacity;if(!spImportGraphColorCandidate(s,&native))return false;if(native.wideConstraints||native.wideConstraintCount)return false;/* Released solver scratch may retain non-null values; export never reads it. */native.wideConstraints=(struct b2ContactConstraintWide*)(uintptr_t)1;native.wideConstraintCount=2147483647;return spExportGraphColor(&native,out,cs,js);}
